PALE = '#f4f7fb'


def fmt_int(value: float | int) -> str:
    return f'{int(round(value)):,}'


def fmt_pct(value: float, digits: int = 1) -> str:
    return f'{value:.{digits}f}%'


def fmt_num(value: float, digits: int = 2) -> str:
    return f'{value:,.{digits}f}'


def classify_regime(row: pd.Series) -> str:
    mm = row['MEAN_MOTION']
    ecc = row['ECCENTRICITY']
    if mm > 14:
        return 'LEO'
    if 0.95 <= mm <= 1.05 and ecc < 0.1:
        return 'GEO'
    if ecc >= 0.1 or mm < 0.95:
        return 'HEO'
    return 'MEO'


def constellation_label(name: str) -> str:
    n = str(name).upper().strip()
    if n.startswith('STARLINK'):
        return 'Starlink'
    if n.startswith('ONEWEB'):
        return 'OneWeb'
    if n.startswith('KUIPER'):
        return 'Kuiper'
    if n.startswith('YAOGAN'):
        return 'Yaogan'
    if n.startswith('FLOCK'):
        return 'Flock'
    if n.startswith('QIANFAN'):
        return 'Qianfan'
    if n.startswith('IRIDIUM'):
        return 'Iridium'
    if n.startswith('LEMUR'):
        return 'Lemur'
    if n.startswith('BEIDOU') or 'BEIDOU' in n:
        return 'BeiDou'
    if 'NAVSTAR' in n:
        return 'GPS/Navstar'
    if 'GALILEO' in n:
        return 'Galileo'
    if 'GLONASS' in n:
        return 'GLONASS'
    if n.startswith('GLOBALSTAR'):
        return 'Globalstar'
    if n.startswith('ICEYE'):
        return 'ICEYE'
    if n.startswith('GAOFEN'):
        return 'Gaofen'
    if n.startswith('SKYSAT'):
        return 'SkySat'
    if n.startswith('NUSAT'):
        return 'NuSat'
    return 'Other named systems / individual missions'


def svg_bar_chart(data: list[tuple[str, float, str]], width=860, height=390, title='', x_label='Satellites', note='') -> str:
    margin = dict(top=52, right=120, bottom=48, left=210)
    plot_w = width - margin['left'] - margin['right']
    row_h = (height - margin['top'] - margin['bottom']) / max(len(data), 1)
    max_val = max([v for _, v, _ in data] or [1])
    ticks = 5
    parts = [f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="{html.escape(title)}">']
    parts.append(f'<rect width="{width}" height="{height}" fill="white" rx="14"/>')
    if title:
        parts.append(f'<text x="24" y="30" class="chart-title">{html.escape(title)}</text>')
    for i in range(ticks + 1):
        x = margin['left'] + plot_w * i / ticks
        val = max_val * i / ticks
        parts.append(f'<line x1="{x:.1f}" y1="{margin["top"]}" x2="{x:.1f}" y2="{height-margin["bottom"]}" stroke="{GRID}" stroke-width="1"/>')
        parts.append(f'<text x="{x:.1f}" y="{height-22}" text-anchor="middle" class="axis">{fmt_int(val)}</text>')
    for idx, (label, val, color) in enumerate(data):
        y = margin['top'] + idx * row_h + row_h * 0.18
        bar_h = row_h * 0.58
        w = plot_w * val / max_val if max_val else 0
        parts.append(f'<text x="{margin["left"]-12}" y="{y+bar_h*0.67:.1f}" text-anchor="end" class="axis label">{html.escape(label)}</text>')
        parts.append(f'<rect x="{margin["left"]}" y="{y:.1f}" width="{w:.1f}" height="{bar_h:.1f}" rx="5" fill="{color}"/>')
        parts.append(f'<text x="{margin["left"]+w+8:.1f}" y="{y+bar_h*0.67:.1f}" class="value">{fmt_int(val)}</text>')
    parts.append(f'<text x="{width/2:.1f}" y="{height-5}" text-anchor="middle" class="axis">{html.escape(x_label)}</text>')
    if note:
        parts.append(f'<text x="24" y="{height-12}" class="caption">{html.escape(note)}</text>')
    parts.append('</svg>')
    return ''.join(parts)


def svg_stacked_bar(segments: list[tuple[str, float, str]], width=860, height=132, title='') -> str:
    total = sum(v for _, v, _ in segments) or 1
    x0, y, w, h = 28, 54, width - 56, 32
    parts = [f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="{html.escape(title)}">']
    parts.append(f'<rect width="{width}" height="{height}" fill="white" rx="14"/>')
    parts.append(f'<text x="24" y="30" class="chart-title">{html.escape(title)}</text>')
    x = x0
    for label, value, color in segments:
        sw = w * value / total
        parts.append(f'<rect x="{x:.1f}" y="{y}" width="{sw:.1f}" height="{h}" fill="{color}"/>')
        if sw > 70:
            parts.append(f'<text x="{x+sw/2:.1f}" y="{y+21}" text-anchor="middle" fill="white" class="bar-label">{html.escape(label)}</text>')
        x += sw
    lx = 28
    ly = 112
    for label, value, color in segments:
        parts.append(f'<rect x="{lx}" y="{ly-10}" width="10" height="10" fill="{color}" rx="2"/>')
        parts.append(f'<text x="{lx+16}" y="{ly}" class="axis">{html.escape(label)} {fmt_pct(value/total*100)}</text>')
        lx += 150
    parts.append('</svg>')
    return ''.join(parts)


def nice_step(max_val: float, target_ticks: int = 6) -> int:
    raw = max_val / target_ticks if max_val else 1
    power = 10 ** math.floor(math.log10(raw))
    for mult in [1, 2, 5, 10]:
        if raw <= mult * power:
            return int(mult * power)
    return int(10 * power)


def svg_line_chart(points: list[tuple[int, int]], width=940, height=460, title='') -> str:
    margin = dict(top=58, right=42, bottom=58, left=70)
    plot_w = width - margin['left'] - margin['right']
    plot_h = height - margin['top'] - margin['bottom']
    min_x, max_x = min(x for x, _ in points), max(x for x, _ in points)
    max_y = max(y for _, y in points)
    step = nice_step(max_y)
    y_max = math.ceil(max_y / step) * step
    def sx(x):
        return margin['left'] + (x - min_x) / (max_x - min_x) * plot_w if max_x > min_x else margin['left']
    def sy(y):
        return margin['top'] + plot_h - y / y_max * plot_h if y_max else margin['top'] + plot_h
    coords = ' '.join(f'{sx(x):.1f},{sy(y):.1f}' for x, y in points)
    area = f'M {sx(points[0][0]):.1f},{sy(0):.1f} L ' + ' L '.join(f'{sx(x):.1f},{sy(y):.1f}' for x, y in points) + f' L {sx(points[-1][0]):.1f},{sy(0):.1f} Z'
    parts = [f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="{html.escape(title)}">']
    parts.append(f'<rect width="{width}" height="{height}" fill="white" rx="14"/>')
    parts.append(f'<text x="24" y="32" class="chart-title">{html.escape(title)}</text>')
    for yv in range(0, y_max + 1, step):
        y = sy(yv)
        parts.append(f'<line x1="{margin["left"]}" y1="{y:.1f}" x2="{width-margin["right"]}" y2="{y:.1f}" stroke="{GRID}"/>')
        parts.append(f'<text x="{margin["left"]-12}" y="{y+4:.1f}" text-anchor="end" class="axis">{fmt_int(yv)}</text>')
    for year in range((min_x // 5) * 5, max_x + 1, 5):
        if year < min_x:
            continue
        x = sx(year)
        parts.append(f'<line x1="{x:.1f}" y1="{margin["top"]}" x2="{x:.1f}" y2="{height-margin["bottom"]}" stroke="{GRID}" stroke-width="1"/>')
        parts.append(f'<text x="{x:.1f}" y="{height-28}" text-anchor="middle" class="axis">{year}</text>')
    parts.append(f'<path d="{area}" fill="{TEAL}" opacity="0.14"/>')
    parts.append(f'<polyline points="{coords}" fill="none" stroke="{TEAL}" stroke-width="4" stroke-linejoin="round" stroke-linecap="round"/>')
    for x, yv in points:
        if x >= 2019 or yv == max_y:
            parts.append(f'<circle cx="{sx(x):.1f}" cy="{sy(yv):.1f}" r="4" fill="{TEAL}" stroke="white" stroke-width="2"/>')
    for year in [2020, 2025]:
        if min_x <= year <= max_x:
            parts.append(f'<line x1="{sx(year):.1f}" y1="{margin["top"]}" x2="{sx(year):.1f}" y2="{height-margin["bottom"]}" stroke="{GOLD}" stroke-width="2" stroke-dasharray="6 5"/>')
    recent = [(x, y) for x, y in points if x >= 2020]
    if recent:
        label = f'2020–{max_x}: {fmt_int(sum(y for _, y in recent))} active satellites launched'
        parts.append(f'<rect x="{sx(2020)+10:.1f}" y="72" width="320" height="36" rx="7" fill="{PALE}" stroke="{GRID}"/>')
        parts.append(f'<text x="{sx(2020)+24:.1f}" y="95" class="annotation">{html.escape(label)}</text>')
    peak_year, peak_val = max(points, key=lambda p: p[1])
    parts.append(f'<text x="{sx(peak_year)-8:.1f}" y="{sy(peak_val)-13:.1f}" text-anchor="end" class="annotation">Peak: {peak_year} ({fmt_int(peak_val)})</text>')
    parts.append(f'<text x="{width/2:.1f}" y="{height-6}" text-anchor="middle" class="axis">Launch year parsed from OBJECT_ID</text>')
    parts.append('</svg>')
    return ''.join(parts)


def svg_histogram(bins: list[tuple[str, int]], width=860, height=330, title='', color=BLUE) -> str:
    margin = dict(top=50, right=28, bottom=72, left=64)
    plot_w = width - margin['left'] - margin['right']
    plot_h = height - margin['top'] - margin['bottom']
    max_val = max([v for _, v in bins] or [1])
    bar_gap = 4
    bar_w = (plot_w - bar_gap * (len(bins) - 1)) / max(len(bins), 1)
    parts = [f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="{html.escape(title)}">']
    parts.append(f'<rect width="{width}" height="{height}" fill="white" rx="14"/>')
    parts.append(f'<text x="24" y="30" class="chart-title">{html.escape(title)}</text>')
    for i in range(5):
        val = max_val * i / 4
        y = margin['top'] + plot_h - (plot_h * i / 4)
        parts.append(f'<line x1="{margin["left"]}" y1="{y:.1f}" x2="{width-margin["right"]}" y2="{y:.1f}" stroke="{GRID}"/>')
        parts.append(f'<text x="{margin["left"]-10}" y="{y+4:.1f}" text-anchor="end" class="axis">{fmt_int(val)}</text>')
    for idx, (label, val) in enumerate(bins):
        x = margin['left'] + idx * (bar_w + bar_gap)
        h = plot_h * val / max_val if max_val else 0
        y = margin['top'] + plot_h - h
        parts.append(f'<rect x="{x:.1f}" y="{y:.1f}" width="{bar_w:.1f}" height="{h:.1f}" fill="{color}" rx="3"/>')
        if idx % 2 == 0 or len(bins) <= 12:
            parts.append(f'<text x="{x+bar_w/2:.1f}" y="{height-42}" text-anchor="middle" class="axis small" transform="rotate(-35 {x+bar_w/2:.1f},{height-42})">{html.escape(label)}</text>')
    parts.append('</svg>')
    return ''.join(parts)


def table_html(headers: Iterable[str], rows: Iterable[Iterable[object]]) -> str:
    out = ['<table><thead><tr>']
    out += [f'<th>{html.escape(str(h))}</th>' for h in headers]
    out.append('</tr></thead><tbody>')
    for row in rows:
        out.append('<tr>')
        out += [f'<td>{html.escape(str(cell))}</td>' for cell in row]
        out.append('</tr>')
    out.append('</tbody></table>')
    return ''.join(out)


