def nice_step(max_val: float, target_ticks: int = 6) -> int:
    raw = max_val / target_ticks if max_val else 1
    power = 10 ** math.floor(math.log10(raw))
    for mult in [1, 2, 5, 10]:
        if raw <= mult * power:
            return int(mult * power)
    return int(10 * power)


